/// <summary>
/// Returns a formatted string representation of this data size.
/// </summary>
/// <param name="format">A standard or custom numeric format string.</param>
/// <param name="provider">An object that supplies culture-specific formatting information.</param>
/// <returns>A formatted string representing this data size.</returns>
public string ToString(string? format, IFormatProvider? formatProvider = null)
{
    format ??= "0.## ";
    formatProvider ??= CultureInfo.CurrentCulture;

    if (!format.Contains('#') && !format.Contains('0'))
    {
        format = "0.## " + format;
    }

    if (format.Contains("#.##", StringComparison.Ordinal))
    {
        format = format.Replace("#.##", "0.##");
    }

    // Check for explicit unit symbols and format the corresponding value
    if (format.Contains(TerabyteSymbol, StringComparison.OrdinalIgnoreCase))
        return Terabytes.ToString(format.Replace(TerabyteSymbol, "", StringComparison.OrdinalIgnoreCase), formatProvider) + TerabyteSymbol;

    if (format.Contains(GigabyteSymbol, StringComparison.OrdinalIgnoreCase))
        return Gigabytes.ToString(format.Replace(GigabyteSymbol, "", StringComparison.OrdinalIgnoreCase), formatProvider) + GigabyteSymbol;

    if (format.Contains(MegabyteSymbol, StringComparison.OrdinalIgnoreCase))
        return Megabytes.ToString(format.Replace(MegabyteSymbol, "", StringComparison.OrdinalIgnoreCase), formatProvider) + MegabyteSymbol;

    if (format.Contains(KilobyteSymbol, StringComparison.OrdinalIgnoreCase))
        return Kilobytes.ToString(format.Replace(KilobyteSymbol, "", StringComparison.OrdinalIgnoreCase), formatProvider) + KilobyteSymbol;

    if (format.Contains(ByteSymbol, StringComparison.Ordinal))
        return Bytes.ToString(format.Replace(ByteSymbol, ""), formatProvider) + ByteSymbol;

    if (format.Contains(BitSymbol, StringComparison.Ordinal))
        return ((double)Bits).ToString(format.Replace(BitSymbol, ""), formatProvider) + BitSymbol;

    GetLargestWholeNumber(out var value, out var symbol);
    return $"{value.ToString(format, formatProvider)} {symbol}";
}

