         {
             format = format.Replace("#.##", "0.##");
         }

         // Check for explicit unit symbols and format the corresponding value
         if (format.Contains(TerabyteSymbol, StringComparison.OrdinalIgnoreCase))
             return Terabytes.ToString(format.Replace(TerabyteSymbol, "", StringComparison.OrdinalIgnoreCase), formatProvider) + TerabyteSymbol;

         if (format.Contains(GigabyteSymbol, StringComparison.OrdinalIgnoreCase))
